-- Compare structure and effective privileges, never fixture data.
select jsonb_build_object(
 'functions',(select jsonb_agg(jsonb_build_object('name',p.proname,'args',pg_get_function_arguments(p.oid),'return',pg_get_function_result(p.oid),'owner',pg_get_userbyid(p.proowner),'definer',p.prosecdef,'config',p.proconfig,'body',p.prosrc,'anon',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated',has_function_privilege('authenticated',p.oid,'EXECUTE'),'service_role',has_function_privilege('service_role',p.oid,'EXECUTE'),'public',exists(select 1 from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) where grantee=0 and privilege_type='EXECUTE')) order by p.proname)
 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('app_mutate','app_snapshot','internal_mutation_core','internal_snapshot_core','internal_can_receive_communication','can_read_message','can_receive_announcements','authorize_notification_attempt','finish_notification_attempt','claim_notifications','claim_event_notifications')),
 'policies',(select jsonb_agg(to_jsonb(p) order by tablename,policyname) from pg_policies p where schemaname='public' and tablename in ('guest_contacts','messages','announcements')),
 'rls',(select jsonb_agg(jsonb_build_object('table',c.relname,'enabled',c.relrowsecurity,'forced',c.relforcerowsecurity) order by c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('guest_contacts','messages','announcements')),
 'columns',(select jsonb_agg(jsonb_build_object('table',table_name,'column',column_name,'type',data_type,'nullable',is_nullable,'default',column_default) order by table_name,column_name) from information_schema.columns where table_schema='public' and (table_name='guest_contacts' and column_name='communications_revoked' or table_name='notification_jobs' and column_name='delivery_started_at')),
 'status_constraint',(select pg_get_constraintdef(oid) from pg_constraint where conrelid='public.notification_jobs'::regclass and conname='notification_jobs_status_check')
);
